dict(case="Gonorrhoea / urethral discharge", src=f"{DYP} (Long case — Gonorrhoea); {IA} ch.132; NACO; CDC 2021",
 qa=[
 ("What is gonorrhoea and its organism?", ["STI caused by Neisseria gonorrhoeae — Gram-negative intracellular kidney/bean-shaped diplococci; infects columnar/transitional epithelium (urethra, endocervix, rectum, pharynx, conjunctiva)"]),
 ("Why does gonorrhoea not cause vaginitis in adult women?", ["Adult vagina has stratified squamous epithelium (oestrogen) resistant to gonococci; prepubertal girls (thin columnar-like epithelium) get vulvovaginitis"]),
 ("Clinical features in men?", ["Incubation 2–5 days; profuse purulent urethral discharge, dysuria, meatal oedema; complications: epididymitis, prostatitis, periurethral abscess, Tysonian/Littre gland abscess, urethral stricture"]),
 ("Gonococcal vs non-gonococcal urethritis?", ["Gonococcal: short incubation, profuse purulent discharge, Gram-negative intracellular diplococci", "NGU: longer incubation (1–3 weeks), scanty mucoid discharge, pus cells ≥2/oil immersion field without diplococci — Chlamydia trachomatis (D–K), Mycoplasma genitalium, Ureaplasma, Trichomonas"]),
 ("What is disseminated gonococcal infection?", ["Arthritis–dermatitis syndrome: fever, migratory polyarthralgia, tenosynovitis and few acral haemorrhagic pustules on erythematous base; or purulent monoarthritis; risk with menstruation, pregnancy, late complement (C5–C9) deficiency, SLE"]),
 ("Investigations?", ["Gram stain of urethral smear (sensitivity >95% in symptomatic men; poor in women), culture on Thayer–Martin/modified New York City medium (antibiotic sensitivity), NAAT/PCR (most sensitive, multiple sites incl. pharynx and rectum)", "Screen for chlamydia, syphilis, HIV, hepatitis B/C"]),
 ("Treatment?", ["CDC 2020/2021: ceftriaxone 500 mg IM single dose (1 g if ≥150 kg); add doxycycline 100 mg twice daily × 7 days if chlamydia not excluded", "NACO syndromic: grey kit (kit 1) — cefixime 400 mg + azithromycin 1 g single dose for urethral discharge/cervicitis", "Treat partners; abstain for 7 days; test of cure for pharyngeal infection"]),
 ("Why high-dose ceftriaxone?", ["Rising MICs and ceftriaxone-resistant strains; pharyngeal infection needs higher levels; azithromycin resistance makes dual therapy less reliable"]),
 ("Ophthalmia neonatorum — prevention and treatment?", ["Prophylaxis at birth: 0.5% erythromycin or 1% tetracycline eye ointment (silver nitrate 1% — Credé method, historical)", "Treatment: ceftriaxone 25–50 mg/kg IM single dose (max 125 mg) and saline irrigation"]),
 ],
 spot=["Profuse purulent urethral discharge with Gram-negative intracellular diplococci — gonococcal urethritis"]),

